from lib import *
S = SS('n52')
steps = [
    step("gin.Default()(Logger + Recovery)下的四种情形,真实进程加 curl:GET /direct(handler 里直接 panic)→ 500,进程继续运行,再请求 /ok 仍是 200;GET /go(handler 起的 goroutine 里 panic)→ curl 收到 Empty reply(连接被断开),进程以退出码 2 退出,再请求 /ok 连接被拒绝;GET /go-after(handler 已经返回 200 之后 300 ms,goroutine 才 panic)→ 客户端先收到 200,随后进程同样崩溃(退出码 2);GET /guard(goroutine 里自己 recover)→ 500 和捕获的信息,进程继续运行。", t=tl(S(1)), mark=lidx(S(1), 'GET /go ', 'GET /go-after'), done=lidx(S(1), 'GET /direct', 'GET /guard'), b=bars([['handler 里直接 panic', 0, '进程存活'], ['goroutine 里 panic', 2, '进程崩溃,退出码 2'], ['返回后 goroutine panic', 2, '进程崩溃,退出码 2'], ['goroutine 里 recover', 0, '进程存活']], 2, mark=[1, 2], done=[0, 3]), kv=KV([['Recovery', '只管当前请求所在 goroutine 的 panic'], ['其它 goroutine', 'panic 没人接,整个进程退出码 2'], ['handler 返回之后', '同样会崩溃,没有任何请求上下文可查']], ['Recovery'])),
    step("崩溃时进程的输出:panic: handler 返回之后 goroutine 才 panic、goroutine 23 [running]:、栈帧 main.main.func5.1()、以及关键的 created by main.main.func5 in goroutine 21(这个 panic 是谁在哪里启动的),最后进程以退出码 2 退出。这里没有 Gin 的 [Recovery] 日志,因为没有经过 Recovery 中间件;“created by” 是定位的唯一线索。", t=tl(S(2)), mark=lidx(S(2), 'created by', 'panic: handler 返回之后', '退出码 2'), done=lidx(S(2), 'goroutine 23 [running]'), kv=KV([['没有 Recovery 日志', 'panic 没经过中间件'], ['created by', '指出是哪个 handler 起的 goroutine'], ['退出码', '2']], ['created by'])),
    step("无辜的请求也会一起死:/slow 需要 800 ms,200 ms 时另一个请求触发 goroutine 里的 panic——/slow 得到 Empty reply(连接被切断),进程退出码 2;对照:触发的是 handler 里直接 panic,同时在途的 /slow 正常返回 slow done,进程继续运行。一个 goroutine 的 panic 会毁掉所有正在处理的请求。", t=tl(S(3)), mark=lidx(S(3), '触发 /go-after'), done=lidx(S(3), '触发 /direct'), b=bars([['goroutine panic 时的 /slow', 0, '失败(Empty reply)'], ['handler panic 时的 /slow', 1, '成功']], 1, mark=[0], done=[1]), kv=KV([['goroutine panic', '整个进程退出,所有在途请求失败'], ['handler panic', '只影响自己的请求']], ['goroutine panic'])),
    step("安全写法:自己写一个 safeGo,在 goroutine 里 defer recover,把 panic 记录成日志(带栈)并回调通知。/safego:后台任务写 nil map panic,被捕获后通过 channel 交回 handler,handler 返回 500 和“后台任务失败:assignment to entry in nil map”,进程继续运行;/safego-after:handler 已经返回 200,后台任务才 panic,日志里有“捕获 panic: handler 已返回,后台任务 panic”,再请求 /ok 仍是 200。", t=tl(S(4)), mark=lidx(S(4), '捕获 panic'), done=lidx(S(4), '/safego ', '/safego-after'), kv=KV([['safeGo', 'goroutine 里 defer recover + 记日志'], ['结果交回 handler', '用 channel / error,不要直接写已结束的响应'], ['原则', '每个自己起的 goroutine 都要有 recover']], ['原则'])),
]
A = mkartn('n52', 52, 'Gin,goroutine,panic,Recovery,崩溃,Go,真实验证,动画演示',
    '用真实进程实测 handler 里起的 goroutine 发生 panic:Recovery 管不到,整个进程以退出码 2 崩溃(即使 handler 早已返回),同时在途的其它请求也全部失败;handler 里直接 panic 则被 Recovery 接住;给 goroutine 加 recover 的 safeGo 写法能让服务继续运行。',
    '在 handler 或中间件里 go func() {...}() 起一个 goroutine,里面 panic 了,Recovery 能接住吗?这篇起真实的服务进程,用 curl 请求,看进程是否存活、退出码、其它在途请求的命运,最后给出一个可用的 safeGo 写法。',
    [('退出码 2', 'goroutine 里 panic 时整个进程的退出码——Recovery 没有拦住'), ('0 / 1', '另一个请求触发 goroutine panic 时,同时在途的 /slow 请求的成功数(handler panic 时是 1 / 1)'), ('存活', '用 safeGo(goroutine 里 recover)后,panic 被捕获,服务继续处理请求')],
    [('Recovery 的作用域', '<p><code>Recovery</code> 是一个 <code>defer + recover</code> 中间件,只能捕获<b>同一个 goroutine</b> 里的 panic。handler 里直接 panic 会被接住,返回 500 并继续服务;handler 里起的 goroutine 是另一条调用栈,它的 panic 没有任何人接,Go 运行时直接终止整个进程。</p>'),
     ('崩溃长什么样', '<p>进程输出 <code>panic: …</code>、<code>goroutine N [running]</code> 和栈帧,然后退出码 2;没有 Gin 的 <code>[Recovery]</code> 日志。最有用的线索是 <code>created by …</code> 一行,它告诉你这个 goroutine 是在哪里启动的。即使 handler 早已返回,后台 goroutine 的 panic 也会同样崩溃,这时已经没有请求上下文可以排查。</p>'),
     ('代价是全局的', '<p>一个 goroutine 的 panic 会让所有正在处理的请求同时失败(连接被切断),而不是只影响出错的那个。生产环境里这是比 handler 里 panic 严重得多的故障。</p>'),
     ('写法', '<p>每个自己起的 goroutine 开头都应该 <code>defer func() { if e := recover(); e != nil { ... } }()</code>。可以封装成 <code>safeGo</code>:捕获后记录日志(带 <code>debug.Stack()</code>)并通知调用方;如果 handler 还在等结果,通过 channel 把错误交回 handler 来写响应;如果 handler 已经返回,就只记日志、上报监控,不要再碰已经结束的 <code>*gin.Context</code>(需要用 <code>c.Copy()</code>,见前面的文章)。</p>')],
    steps,
    [ENV_N_GIN + '。服务端是编译好的真实二进制(gin.Default(),端口 9772 起),客户端是 curl;进程是否存活用 Python 的 Popen.poll,退出码来自进程;栈输出中的地址被整理成 (…);每种情形各一次',
     '没有验证:errgroup、sync.WaitGroup.Go 等标准写法下的 panic 传播;recover 之后是否应该继续运行(是否有损坏状态,取决于业务);runtime.Goexit;cgo 与信号导致的崩溃;Kubernetes 重启对服务可用性的影响;Gin 的 gin-contrib 里是否有现成的 safe goroutine 工具'],
    'goroutine 里的 panic')
